import java.util.*;
import java.io.*;

public class Main {
    public static char[] str;
    public static String[] validEndings = {"00", "25", "50", "75"};
    public static long result;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        str = br.readLine().toCharArray();
        result = 0;

        // Handle single digit case
        if (str.length == 1) {
            if (str[0] == '0' || str[0] == '_') {
                result = 1; // only 0 is valid
            } else if (str[0] == 'X') {
                result = 1; // X can be 0
            }
            System.out.println(result);
            br.close();
            return;
        }

        // Try each valid ending for divisibility by 25
        for (String ending : validEndings) {
            if (isValidEnding(ending)) {
                countValidNumbers(ending);
            }
        }

        System.out.println(result);
        br.close();
    }

    public static boolean isValidEnding(String ending) {
        char first = str[str.length - 2];
        char second = str[str.length - 1];
        char expectedFirst = ending.charAt(0);
        char expectedSecond = ending.charAt(1);

        // Check if the ending is possible
        if (first != '_' && first != 'X' && first != expectedFirst) return false;
        if (second != '_' && second != 'X' && second != expectedSecond) return false;

        // Handle X constraints
        if (first == 'X' && second == 'X') {
            // Both are X, they must be the same digit, but ending requires different digits for most cases
            // Only "00" has same digits, so only valid for "00"
            if (ending.equals("00")) return true;
            return false;
        }

        // Check if X constraints conflict with the ending
        if (first == 'X') {
            // All X must be same digit, so if second is also X, it must match
            if (second == 'X') return ending.charAt(0) == ending.charAt(1);
            // If second is fixed, X must match expectedFirst
            return true;
        }

        if (second == 'X') {
            // If first is fixed, X must match expectedSecond
            return true;
        }

        return true;
    }

    public static void countValidNumbers(String ending) {
        char firstEnd = ending.charAt(0);
        char secondEnd = ending.charAt(1);

        // Determine what digit X must be if present in the last two positions
        char xDigit = 'n'; // 'n' means no X constraint from ending
        if (str[str.length - 2] == 'X' || str[str.length - 1] == 'X') {
            // If both are X, they must be same, so only valid for "00"
            if (str[str.length - 2] == 'X' && str[str.length - 1] == 'X') {
                if (ending.equals("00")) {
                    xDigit = '0';
                } else {
                    return; // invalid for other endings
                }
            } else if (str[str.length - 2] == 'X') {
                xDigit = firstEnd;
            } else {
                xDigit = secondEnd;
            }
        }

        // Check for leading zero constraint
        if (str[0] == '0') return; // original string starts with 0, invalid
        if (str[0] == 'X' && xDigit != 'n' && xDigit == '0') return; // X at start would be 0
        if (str[0] == '_' && xDigit == '0') {
            // If X is constrained to 0 and first char is _, we need to be careful
            // But _ can be any digit, so we'll handle in counting
        }

        long count = 1;
        boolean xUsed = (xDigit != 'n');

        // Process each position except last two
        for (int i = 0; i < str.length - 2; i++) {
            if (str[i] == '_') {
                if (i == 0) {
                    count *= 9; // can't be 0
                } else {
                    count *= 10;
                }
            } else if (str[i] == 'X') {
                if (i == 0) {
                    count *= 9; // can't be 0
                } else {
                    count *= 10;
                }
            }
        }

        // Check if X constraint affects leading zero
        if (str[0] == 'X' && xDigit == '0') {
            // X at start would be 0, invalid
            return;
        }

        // Special case: if the entire number would be 0
        boolean allZero = true;
        for (int i = 0; i < str.length; i++) {
            if (str[i] != '0' && str[i] != '_' && str[i] != 'X') {
                allZero = false;
                break;
            }
            if (str[i] == 'X' && xDigit != '0') {
                allZero = false;
                break;
            }
        }

        if (allZero && str.length > 1) {
            // "00" or "000" etc. is actually 0, which is divisible by 25
            // But leading zeros make it invalid except for single 0
            // However, problem says 0000 has three leading zeroes, so it's invalid
            // Only single "0" is valid
            if (str.length == 1) {
                result += 1;
            }
            return;
        }

        result += count;
    }
}
